  ],
  "spacing": {
    "baseUnit": null,
    "density": "compact",
    "pageMaxWidth": "1440px",
    "sectionGap": "120-160px",
    "cardPadding": "20px",
    "elementGap": "10px",
    "radius": {
      "tags": "4px",
      "cards": "8px",
      "pills": "100px",
      "badges": "80px",
      "inputs": "4px",
